import React from 'react';
import './logIn.css';
import foobarImage from './foobar3.jpg';
import { useNavigate } from 'react-router-dom';
import { useState } from 'react';



function LogIn({setActiveUser, usersList}) {

  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showInvalidMessage, setShowInvalidMessage] = useState(false);
  



  const handleLogInClick = () => {
     if (usersList.length > 0) {
      const validUser = usersList.find((user) => user.email === email && user.password === password);
      if (validUser) {
        setActiveUser(validUser);
        navigate('HomePage');
      } else {
        setShowInvalidMessage(true);
      } 
    } else {
      setShowInvalidMessage(true);
    }
  };

  const handleSignupClick = () => {
    navigate('SignUp');
  };

  return (
    <header id="header">
      <div className="layer"></div>
      <div className="main">
        <div className="left">
          <img src={foobarImage} alt="" />
          <p>Connect with friends and the world around you on Foobar.</p>
        </div>
        <div className="right">
          <div id="form">
            <div className="form_body">
              <input
                type="text"
                placeholder="Email or phone number"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
              />
              <input
                type="password"
                placeholder="Password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
              />
              {/* Show invalid message if needed */}
              {showInvalidMessage && <p id="error">Invalid credentials. Please try again.</p>} 
              <button className="login" onClick={handleLogInClick}>
                Log In
              </button>
              <p className="forget">forgot password?</p>
              <hr />
              <button className="create" onClick={handleSignupClick}>
                Create new account
              </button>
            </div>
          </div>
        </div>
      </div>
    </header>

  );
}

export default LogIn;
